/**
 * Offline Philippine address data (region -> province -> city/municipality -> barangay).
 *
 * Source: Philippine Statistics Authority (PSA), Philippine Standard Geographic Code (PSGC).
 * Licence: CC BY 4.0 - PSA must be acknowledged as the source (the address form shows this).
 * The JSON files in src/assets/psgc/ are generated by tools/build_psgc.py from PSA's official
 * "PSGC Publication Datafile" (xlsx). To update them, download the newest xlsx and run that script again.
 *
 * No network service, API key or billing is involved: the files are bundled inside the app.
 */

export interface PsgcRegion {
  c: string;
  n: string;
  file: string;
  apiCode?: string;
}
export interface PsgcProvince { c: string; n: string; }
/** p = province code, or '' for NCR cities and independent cities that have no province parent. */
export interface PsgcCity { c: string; n: string; p: string; t: 'C' | 'M'; }
export interface PsgcRegionData {
  provinces: PsgcProvince[];
  cities: PsgcCity[];
  barangays: Record<string, string[]>;
}
export interface PsgcIndex { source: string; publication_date: string; regions: PsgcRegion[]; }

export const NCR_CODE = '1300000000';

/**
 * Text saved in user_addresses.province for cities that have no province.
 * NCR keeps the value 'NCR' (matches your existing data). Change the second value if you prefer another word.
 */
export const NCR_PROVINCE_VALUE = 'NCR';
export const INDEPENDENT_PROVINCE_VALUE = 'Independent City';

const BASE = 'assets/psgc/';
const PSGC_API = 'https://psgc.gitlab.io/api/';
let indexPromise: Promise<PsgcIndex> | null = null;
const regionCache = new Map<string, Promise<PsgcRegionData>>();
const barangayCache = new Map<string, Promise<string[]>>();

async function fetchJson(url: string): Promise<any> {
  const response = await fetch(url);
  if (!response.ok) throw new Error(`Request failed (${response.status})`);
  return response.json();
}

async function getJson(file: string): Promise<any> {
  const response = await fetch(BASE + file);
  if (!response.ok) throw new Error('Local PSGC file is missing');
  return response.json();
}

export function loadPsgcIndex(): Promise<PsgcIndex> {
  if (!indexPromise) {
    indexPromise = getJson('index.json').catch(async () => {
      try {
        const rows = await fetchJson(`${PSGC_API}regions/`);

        const regions: PsgcRegion[] = rows
          .map((r: any) => {
            // Keep the API's region code separate from the code used
            // by the app to identify the region.
            const apiCode = String(r.code ?? r.psgcCode ?? '');
            const code = String(
              r.psgc10DigitCode ?? r.psgcCode ?? r.code ?? ''
            );
            const name = String(r.name ?? r.regionName ?? '');

            return {
              c: code,
              n: name,
              file: code,
              apiCode
            };
          })
          .filter((r: PsgcRegion) => r.c && r.n && r.apiCode);

        if (!regions.length) {
          throw new Error('The PSGC API returned no usable regions.');
        }

        return {
          source: 'Philippine Statistics Authority PSGC via psgc.gitlab.io',
          publication_date: 'Live PSGC API',
          regions
        } as PsgcIndex;
      } catch {
        throw new Error(
          'Unable to load Philippine address data. Check your internet connection and try again.'
        );
      }
    });

    indexPromise.catch(() => {
      indexPromise = null;
    });
  }

  return indexPromise;
}

export function loadPsgcRegion(region: PsgcRegion): Promise<PsgcRegionData> {
  if (!region || !region.c) {
    return Promise.reject(new Error('Could not identify the selected region. Please select National Capital Region (NCR) again.'));
  }
  // API-created region records may not include the bundled JSON filename.
  if (!region.file) region.file = String(region.c);
  let promise = regionCache.get(region.file);
  if (!promise) {
    promise = getJson(region.file).catch(async () => {
      try {
        const regionCode = String(region.apiCode ?? '');

      const [provinces, cities] = await Promise.all([
          fetchJson(`${PSGC_API}regions/${regionCode}/provinces/`),
          fetchJson(`${PSGC_API}regions/${regionCode}/cities-municipalities/`)
        ]);
        return {
          provinces: provinces.map((p: any) => ({ c: String(p.code), n: String(p.name) })),
          cities: cities.map((c: any) => ({
            c: String(c.code), n: String(c.name), p: String(c.provinceCode || ''),
            t: 'C'
          })),
          barangays: {}
        } as PsgcRegionData;
      } catch {
        throw new Error('Unable to load Philippine address data. Check your internet connection and try again.');
      }
    });
    regionCache.set(region.file, promise);
    promise.catch(() => regionCache.delete(region.file));
  }
  return promise;
}

export function loadPsgcBarangays(cityCode: string): Promise<string[]> {
  if (!barangayCache.has(cityCode)) {
    const request = fetchJson(`${PSGC_API}cities-municipalities/${cityCode}/barangays/`)
      .then((rows: any[]) => rows.map((b: any) => String(b.name)).sort((a, b) => a.localeCompare(b)))
      .catch(() => {
        barangayCache.delete(cityCode);
        throw new Error('Unable to load barangays. Check your internet connection and try again.');
      });
    barangayCache.set(cityCode, request);
  }
  return barangayCache.get(cityCode)!;
}

/** Value saved in user_addresses.region. NCR stays 'NCR' so older saved addresses keep matching. */
export function regionValue(region: PsgcRegion): string {
  return region.c === NCR_CODE ? 'NCR' : region.n;
}

export function independentProvinceValue(region: PsgcRegion): string {
  return region.c === NCR_CODE ? NCR_PROVINCE_VALUE : INDEPENDENT_PROVINCE_VALUE;
}

export function independentProvinceLabel(region: PsgcRegion): string {
  return region.c === NCR_CODE ? 'NCR (no province)' : 'Independent cities (no province)';
}

/** "City of Las Piñas", "Las Pinas City" and "Las Piñas" all become "laspinas"; "Barangay 123" becomes "123". */
export function normalizeName(value: unknown): string {
  return String(value ?? '')
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/\b(city of|municipality of|city|barangay|brgy|bgy)\b/g, '')
    .replace(/[^a-z0-9]/g, '');
}

export function findRegion(regions: PsgcRegion[], saved: string): PsgcRegion | undefined {
  const wanted = normalizeName(saved);
  if (!wanted) return undefined;
  if (wanted === 'ncr') return regions.find(r => r.c === NCR_CODE);
  return regions.find(r => normalizeName(regionValue(r)) === wanted) ||
         regions.find(r => normalizeName(r.n) === wanted);
}

/**
 * Finds the city/municipality named by any of `cityNames` (best candidate first).
 * Looks in `preferredRegion` first, then every other region. Returns null when nothing matches or when
 * the name is ambiguous (for example "San Fernando" exists in two provinces) and `hints` cannot decide.
 */
export async function locateCity(
  regions: PsgcRegion[],
  preferredRegion: PsgcRegion | undefined,
  cityNames: string[],
  hints: string[] = []
): Promise<{ region: PsgcRegion; city: PsgcCity; provinceName: string } | null> {
  const wanted = cityNames.map(normalizeName).filter(Boolean);
  if (!wanted.length) return null;
  const hintSet = new Set(hints.map(normalizeName).filter(Boolean));

  const ordered = [
    ...(preferredRegion ? [preferredRegion] : []),
    ...regions.filter(r => r !== preferredRegion)
  ];

  // Best candidate first. Every region is checked so that names that exist in several places
  // (e.g. "San Fernando", "San Juan") are never guessed.
  for (const name of wanted) {
    const all: { region: PsgcRegion; city: PsgcCity; provinceName: string }[] = [];
    for (const region of ordered) {
      const data = await loadPsgcRegion(region);
      for (const city of data.cities) {
        if (normalizeName(city.n) !== name) continue;
        all.push({ region, city, provinceName: data.provinces.find(p => p.c === city.p)?.n || '' });
      }
    }
    if (!all.length) continue;

    let chosen = all;
    if (chosen.length > 1) {
      // Google calls NCR "Metro Manila"; its second-level name is often the province.
      const wantsNcr = hintSet.has('metromanila') || hintSet.has('nationalcapitalregion') || hintSet.has('ncr');
      const byHint = chosen.filter(m =>
        (m.provinceName && hintSet.has(normalizeName(m.provinceName))) || (wantsNcr && m.region.c === NCR_CODE));
      if (byHint.length) chosen = byHint;
    }
    if (chosen.length > 1 && preferredRegion) {
      const inPreferred = chosen.filter(m => m.region === preferredRegion);
      if (inPreferred.length) chosen = inPreferred;
    }
    if (chosen.length === 1) return chosen[0];
    // still ambiguous: try the next candidate name, otherwise let the user choose
  }
  return null;
}